Title: Incorrect LL_DMAMUX_MAX_REQ for STM32G0B0xx

Body:
**Describe the set-up**
Custom board with an STM32G0B0CET6

**Describe the bug**
An incorrect initialization assert prevents the use of DMA when using USART5 peripheral on the STM32G0B0CETx.

**How To Reproduce**
1. Initialize the USART5 peripheral to use DMA for TX. Start the program.

2. The cause of the problem is an assert failed during assert_param(IS_DMA_ALL_REQUEST(hdma->Init.Request)); in stm32g0xx_hal_dma.c at line 170.

The initialization code to reproduce the problem:
    // Configure DMA for USART5 TX
    hdma_usart5_tx.Instance = USART5_TX_DMA_Channel;
    hdma_usart5_tx.Init.Request = DMA_REQUEST_USART5_TX;
    hdma_usart5_tx.Init.Direction = DMA_MEMORY_TO_PERIPH;
    hdma_usart5_tx.Init.PeriphInc = DMA_PINC_DISABLE;
    hdma_usart5_tx.Init.MemInc = DMA_MINC_ENABLE;
    hdma_usart5_tx.Init.PeriphDataAlignment = DMA_PDATAALIGN_BYTE;
    hdma_usart5_tx.Init.MemDataAlignment = DMA_MDATAALIGN_BYTE;
    hdma_usart5_tx.Init.Mode = DMA_NORMAL;
    hdma_usart5_tx.Init.Priority = DMA_PRIORITY_LOW;

    HAL_DMA_Init(&hdma_usart5_tx);

    // Link DMA handle with USART5 handle
    __HAL_LINKDMA(&usart5, hdmatx, hdma_usart5_tx);

    // Enable DMA interrupts
    HAL_NVIC_SetPriority(DMA1_Channel2_3_IRQn, DMA1_Channel2_3_IRQ_PREEMPT_PRIORITY, DMA1_Channel2_3_IRQ_SUB_PRIORITY);
    HAL_NVIC_EnableIRQ(DMA1_Channel2_3_IRQn);

    // Configure USART5 peripheral
    usart5.Instance = USART5;
    usart5.Init.BaudRate = SERIAL_UART_BAUD_RATE;
    usart5.Init.WordLength = UART_WORDLENGTH_8B;
    usart5.Init.StopBits = UART_STOPBITS_1;
    usart5.Init.Parity = UART_PARITY_NONE;
    usart5.Init.Mode = UART_MODE_TX_RX;
    usart5.Init.HwFlowCtl = UART_HWCONTROL_NONE;
    usart5.Init.OverSampling = UART_OVERSAMPLING_16;
    usart5.Init.OneBitSampling = UART_ONE_BIT_SAMPLE_DISABLE;
    usart5.AdvancedInit.AdvFeatureInit = UART_ADVFEATURE_NO_INIT;

    if (HAL_UART_Init(&usart5) != HAL_OK)
    {
        while(1);   // Need to switch out while(1) for proper error handling
    }

    // Enable UART interrupts
    HAL_NVIC_SetPriority(USART3_4_5_6_IRQn, USART3_4_5_6_IRQ_PREEMPT_PRIORITY, USART3_4_5_6_IRQ_SUB_PRIORITY);
    HAL_NVIC_EnableIRQ(USART3_4_5_6_IRQn);


Here is the #define that fails: 
#define IS_DMA_ALL_REQUEST(REQUEST)             ((REQUEST) <= DMA_MAX_REQUEST)

where: DMA_MAX_REQUEST is defined as:

#define DMA_MAX_REQUEST              LL_DMAMUX_MAX_REQ

and 

In stm32g0xx_ll_dmamux.h

#elif defined(STM32G0B0xx)
#define LL_DMAMUX_MAX_REQ                 LL_DMAMUX_REQ_USART4_TX


**Additional context**
Since there are the peripherals USART5 and USART6 that can use DMA on this platform, the proper define should be:

#define LL_DMAMUX_MAX_REQ                 LL_DMAMUX_REQ_USART6_TX

